update country_flag_history set date_start = '1945-08-15', label_fr = 'Corée du Nord sous administration soviétique', label_en = 'Soviet-administered North Korea', notes_fr = 'Après la libération de 1945, le comité populaire du Nord utilise encore le taegukgi traditionnel, avant l''adoption d''un drapeau propre en 1948.', notes_en = 'After liberation in 1945, the northern People''s Committee still used the traditional taegukgi, before adopting its own flag in 1948.', image_url = '/flags/history/kp-1945.svg' where id = 2117 and iso_code = 'kp';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('kp', '/flags/history/kp-1948.svg', '1948-09-08', '1992-12-30', 'République populaire démocratique de Corée (1948-1992)', 'Democratic People''s Republic of Korea (1948–1992)', 'Le drapeau rouge bordé de bleu, à étoile rouge sur disque blanc, est adopté en 1948, sous influence soviétique ; ses spécifications sont précisées en 1992.', 'The blue-edged red flag with a red star on a white disc was adopted in 1948 under Soviet influence; its specifications were refined in 1992.');
